using System;
using UnityEngine;
using QuestTennisTrainer.Physics;
using QuestTennisTrainer.TrainingModes.BallMachine;
using QuestTennisTrainer.TrainingModes.WallPractice;
using QuestTennisTrainer.TrainingModes.ServeTrainer;
using QuestTennisTrainer.XR_Input;

namespace QuestTennisTrainer.Core
{
    /// <summary>
    /// Snapshot of all regulation court landmarks and room-scale boundaries generated by TennisCourtSceneBuilder.
    /// </summary>
    [Serializable]
    public struct CourtSceneLayout
    {
        public float FullCourtLengthMeters;
        public float SinglesWidthMeters;
        public float NetZ;
        public float NetHeightMeters;
        public Vector3 PlayerHomeCenter;
        public float RoomScaleMinX;
        public float RoomScaleMaxX;
        public Vector3 BallMachineMuzzlePosition;
        public Vector3 PracticeWallPosition;
        public Vector3 DeuceServeMarker;
        public Vector3 AdServeMarker;
    }

    /// <summary>
    /// Zero-click procedural scene builder and layout generator for Quest 3 Tennis Trainer.
    /// Constructable both inside Unity 6 (spawning 3D court, net, backboard wall, and ball machine GameObjects)
    /// and in headless .NET / Docker sandboxes for end-to-end training drill verification.
    /// </summary>
    public static class TennisCourtSceneBuilder
    {
        /// <summary>
        /// Computes exact regulation ITF court landmarks and room-scale strike zone bounds.
        /// Player baseline is at Z = 0, Net is at Z = 11.887m, Far Baseline is at Z = 23.774m.
        /// </summary>
        public static CourtSceneLayout ComputeRegulationCourtLayout(
            TennisPhysicsConfig config,
            WallDistancePreset wallPreset = WallDistancePreset.BaselineGroundstrokes12m)
        {
            float netZ = TennisPhysicsConfig.BaselineToNetMeters; // 11.887m
            float fullLength = netZ * 2f;                         // 23.774m
            float maxReach = config.MaxLateralReachMeters > 0f ? config.MaxLateralReachMeters : 1.20f;

            return new CourtSceneLayout
            {
                FullCourtLengthMeters = fullLength,
                SinglesWidthMeters = TennisPhysicsConfig.SinglesCourtWidthMeters, // 8.23m
                NetZ = netZ,
                NetHeightMeters = TennisPhysicsConfig.NetCenterHeightMeters,     // 0.914m
                PlayerHomeCenter = Vector3.zero,
                RoomScaleMinX = -maxReach,
                RoomScaleMaxX = maxReach,
                BallMachineMuzzlePosition = new Vector3(0f, 1.05f, fullLength),
                PracticeWallPosition = new Vector3(0f, 0f, (float)wallPreset),
                DeuceServeMarker = ServeTossController.GetStationaryBaselineMarkerPosition(ServeCourtSide.Deuce),
                AdServeMarker = ServeTossController.GetStationaryBaselineMarkerPosition(ServeCourtSide.Ad)
            };
        }

        /// <summary>
        /// Instantiates and wires a complete, ready-to-run training rig (Bootstrap, Ball, Swept Racket,
        /// Haptics, Ball Machine, Tennis Wall, and Serve Trainer) in a single call.
        /// </summary>
        public static TennisSimulationBootstrap BuildWiredTrainingRig(
            WallDistancePreset wallDistance = WallDistancePreset.BaselineGroundstrokes12m)
        {
            TennisPhysicsConfig cfg = TennisPhysicsConfig.CreateDefault();
            CourtSceneLayout layout = ComputeRegulationCourtLayout(cfg, wallDistance);

#if UNITY_5_3_OR_NEWER
            GameObject rootObj = new GameObject("QuestTennisTrainer_Rig");
            TennisSimulationBootstrap bootstrap = rootObj.AddComponent<TennisSimulationBootstrap>();

            GameObject homeMarkerObj = new GameObject("Player_RoomScale_HomeMarker");
            homeMarkerObj.transform.SetPositionAndRotation(layout.PlayerHomeCenter, Quaternion.identity);

            GameObject ballObj = GameObject.CreatePrimitive(PrimitiveType.Sphere);
            ballObj.name = "TennisBall_120Hz";
            ballObj.transform.localScale = Vector3.one * (TennisPhysicsConfig.BallRadiusMeters * 2f);
            BallAerodynamics ball = ballObj.AddComponent<BallAerodynamics>();

            GameObject racketObj = new GameObject("DominantHand_SweptRacket");
            SweptRacketCollider racket = racketObj.AddComponent<SweptRacketCollider>();
            RacketHapticsController haptics = racketObj.AddComponent<RacketHapticsController>();

            GameObject machineObj = new GameObject("Programmable_BallMachine");
            machineObj.transform.SetPositionAndRotation(layout.BallMachineMuzzlePosition, Quaternion.identity);
            BallMachineController machine = machineObj.AddComponent<BallMachineController>();

            GameObject wallObj = new GameObject("TennisPracticeWall_Backboard");
            wallObj.transform.SetPositionAndRotation(layout.PracticeWallPosition, Quaternion.identity);
            TennisWallController wall = wallObj.AddComponent<TennisWallController>();
            wall.InitializeDefaultTargetZones();
            wall.SetWallDistancePreset(wallDistance);

            GameObject serveObj = new GameObject("TwoHanded_ServeTrainer");
            ServeTossController serve = serveObj.AddComponent<ServeTossController>();

            bootstrap.BindSubsystems(ball, racket, haptics, machine, wall, serve, homeMarkerObj.transform);
            return bootstrap;
#else
            // Headless .NET 8 / Docker Sandbox construction
            TennisSimulationBootstrap bootstrap = new TennisSimulationBootstrap();
            Transform homeMarker = new Transform { position = layout.PlayerHomeCenter };

            BallAerodynamics ball = new BallAerodynamics();
            SweptRacketCollider racket = new SweptRacketCollider();
            RacketHapticsController haptics = new RacketHapticsController();
            BallMachineController machine = new BallMachineController();

            TennisWallController wall = new TennisWallController();
            wall.InitializeDefaultTargetZones();
            wall.SetWallDistancePreset(wallDistance);

            ServeTossController serve = new ServeTossController();

            bootstrap.BindSubsystems(ball, racket, haptics, machine, wall, serve, homeMarker);
            return bootstrap;
#endif
        }
    }
}

